# Simulation using corrected optimal placement strategies
cards = list(range(50, 0, -1))
piles = {1: 0, 2: 0}

for k, card in enumerate(cards):
    turn = k + 1

    if turn % 2 != 0:
        # Grogg's turn (Minimizer). He places the card to minimize |S1 - S2|.
        # Strategy: Place in the pile with the SMALLEST current sum.
        if piles[1] <= piles[2]:
            piles[1] += card
        else:
            piles[2] += card
    else:
        # Winnie's turn (Maximizer). She places the card to maximize |S1 - S2|.
        # Strategy: Place in the pile with the LARGEST current sum.
        if piles[1] >= piles[2]:
            piles[1] += card
        else:
            piles[2] += card

S1 = piles[1]
S2 = piles[2]
difference = abs(S1 - S2)

print(f"Final S1: {S1}")
print(f"Final S2: {S2}")
print(f"Final Difference D: {difference}")
